pub(super) fn handle(
    command: ForeignProcessCommand,
    store: &unicodex_core::ObjectStore,
    format: crate::OutputFormat,
) -> anyhow::Result<i32> {
    match command {
        ForeignProcessCommand::PutCompositionCallReceipt(args) => {
            composition_call_receipt::put_command(
                store,
                &args.construction_receipt,
                &args.call_receipt,
                format,
            )
        }
        ForeignProcessCommand::VerifyCompositionCallReceipt(args) => {
            composition_call_receipt::verify_command(store, &args.cid, format)
        }
        ForeignProcessCommand::PutCompositionProtocolRequirement(args) => {
            composition_protocol_requirement::put_command(
                store,
                &args.composition_receipt,
                &args.protocol_match,
                format,
            )
        }
        ForeignProcessCommand::VerifyCompositionProtocolRequirement(args) => {
            composition_protocol_requirement::verify_command(store, &args.cid, format)
        }
        ForeignProcessCommand::VerifyCallReceipt(args) => {
            runtime_call::verify_receipt_command(store, &args.cid, format)
        }
        ForeignProcessCommand::VerifyCallFailureReceipt(args) => {
            runtime_call::verify_failure_receipt_command(store, &args.cid, format)
        }
        _ => unreachable!("receipt router received an unrelated command"),
    }
}

