    )
}

pub(super) fn assert_rejected_build(output: Output, secrets: &[String]) {
    assert!(!output.status.success());
    assert!(output.stderr.is_empty());
    let rejected: JsonValue = serde_json::from_slice(&output.stdout).unwrap();
    assert_eq!(rejected["accepted"], false);
    assert_eq!(rejected["built"], false);
    assert!(rejected["receipt_cid"].is_null());
    for secret in secrets {
        assert_json_omits(&rejected, secret);
    }
}

pub(super) fn assert_rejected_receipt(output: Output) -> JsonValue {
    assert!(!output.status.success());
    assert!(output.stderr.is_empty());
"}

